<?php
declare(strict_types=1);
require_once __DIR__ . '/../app/bootstrap.php';
$user = require_role('receptionist','stylist');
function sd_mywork_h(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$error=''; $flash=(string)($_SESSION['my_work_flash']??''); unset($_SESSION['my_work_flash']);
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!verify_csrf($_POST['_csrf']??null)) $error='Your security token expired. Refresh the page and try again.';
    else {
        $taskId=filter_var($_POST['task_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
        $status=(string)($_POST['status']??'');
        if (!$taskId || !in_array($status,['pending','in_progress','completed'],true)) $error='Invalid task update.';
        else {
            $check=db()->prepare('SELECT id,status FROM staff_tasks WHERE id=:id AND assigned_to=:uid'); $check->execute(['id'=>(int)$taskId,'uid'=>(int)$user['id']]); $task=$check->fetch();
            if (!$task || $task['status']==='cancelled') $error='This task is unavailable.';
            else {
                $stmt=db()->prepare('UPDATE staff_tasks SET status=:status,completed_at=:completed WHERE id=:id AND assigned_to=:uid AND status<>\'cancelled\'');
                $stmt->execute(['status'=>$status,'completed'=>$status==='completed'?date('Y-m-d H:i:s'):null,'id'=>(int)$taskId,'uid'=>(int)$user['id']]);
                $_SESSION['my_work_flash']='Task status updated.'; header('Location: my-work.php'); exit;
            }
        }
    }
}
$shiftsStmt=db()->prepare('SELECT shift_date,start_time,end_time,location,status,notes FROM staff_shifts WHERE staff_user_id=:uid AND shift_date>=DATE_SUB(CURRENT_DATE,INTERVAL 7 DAY) ORDER BY shift_date,start_time LIMIT 40'); $shiftsStmt->execute(['uid'=>(int)$user['id']]); $shifts=$shiftsStmt->fetchAll();
$tasksStmt=db()->prepare('SELECT id,title,description,due_at,priority,status,created_at FROM staff_tasks WHERE assigned_to=:uid AND status<>\'cancelled\' ORDER BY FIELD(status,\'pending\',\'in_progress\',\'completed\'),due_at IS NULL,due_at,id DESC LIMIT 50'); $tasksStmt->execute(['uid'=>(int)$user['id']]); $tasks=$tasksStmt->fetchAll();
$scheduleStmt=db()->prepare('SELECT day_of_week,is_day_off,start_time,end_time FROM staff_weekly_schedule WHERE staff_user_id=:uid ORDER BY day_of_week'); $scheduleStmt->execute(['uid'=>(int)$user['id']]); $schedule=$scheduleStmt->fetchAll();
$myServices=[]; $commissionTotals=['pending'=>0.0,'approved'=>0.0,'paid'=>0.0]; $myCommissions=[];
if ($user['role']==='stylist') {
    $ss=db()->prepare('SELECT s.name,s.description,s.price,s.duration_minutes FROM stylist_services x JOIN services s ON s.id=x.service_id WHERE x.staff_user_id=:uid AND x.is_active=1 AND s.is_active=1 ORDER BY s.name'); $ss->execute(['uid'=>(int)$user['id']]); $myServices=$ss->fetchAll();
    $ct=db()->prepare('SELECT status,COALESCE(SUM(commission_amount),0) total FROM service_commissions WHERE stylist_user_id=:uid GROUP BY status'); $ct->execute(['uid'=>(int)$user['id']]); foreach($ct->fetchAll() as $r) if(isset($commissionTotals[$r['status']])) $commissionTotals[$r['status']]=(float)$r['total'];
    $cc=db()->prepare('SELECT performed_at,service_name_snapshot,service_price,commission_rate,commission_amount,status FROM service_commissions WHERE stylist_user_id=:uid ORDER BY performed_at DESC,id DESC LIMIT 30'); $cc->execute(['uid'=>(int)$user['id']]); $myCommissions=$cc->fetchAll();
}
$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SalonDiva · My Work</title><style>@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&display=swap');body{margin:0;padding:1.2rem;background:linear-gradient(135deg,#ffc2d1,#ff93b0);font:15px/1.5 Outfit,system-ui,sans-serif;color:#2b1520}.wrap{max-width:1000px;margin:auto;background:#fff6ec;padding:clamp(1rem,3vw,2rem);border-radius:24px;box-shadow:0 22px 70px #8f24452b}.logo{font-size:1.5rem;color:#c8264f;font-weight:800}h1{margin:.2rem 0 1rem}h2{font-size:1.2rem}.card{border:1px solid #eedce2;border-radius:16px;background:#fffdf9;padding:1rem;margin:1rem 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.7rem}.stat{background:#fff;padding:.8rem;border:1px solid #eedce2;border-radius:12px}.stat b{display:block;font-size:1.15rem}.muted{color:#806b73}.notice{padding:.8rem;border-radius:10px;background:#e8f7ed;color:#176b45}.error{padding:.8rem;border-radius:10px;background:#fde8ec;color:#9e263b}table{border-collapse:collapse;width:100%;min-width:600px}th,td{text-align:left;padding:.65rem;border-bottom:1px solid #eedce2;vertical-align:top}.tablewrap{overflow:auto}.btn,button{display:inline-block;border:0;border-radius:999px;background:#2b1520;color:#fff;padding:.55rem .8rem;font:inherit;cursor:pointer}.btn.light{background:#f8e2e9;color:#2b1520}select{font:inherit;padding:.35rem;border:1px solid #dec9d1;border-radius:8px}.badge{display:inline-block;border-radius:999px;padding:.18rem .5rem;background:#f6e1e8;font-size:.8rem}.badge.completed,.badge.paid,.badge.approved{background:#dff3e6;color:#176b45}.badge.pending{background:#fff0c9;color:#765600}.badge.cancelled,.badge.void{background:#f9dfe3;color:#8b2136}a{color:#c8264f}</style></head><body><main class="wrap"><div class="logo">SalonDiva</div><h1>My Work — <?=sd_mywork_h((string)$user['name'])?></h1><p>Your shifts, tasks, and assigned services. You can update the status of your own tasks only.</p><p><a class="btn light" href="dashboard.php">Back to dashboard</a></p><?php if($flash!==''):?><p class="notice"><?=sd_mywork_h($flash)?></p><?php endif;?><?php if($error!==''):?><p class="error"><?=sd_mywork_h($error)?></p><?php endif;?>
<section class="card"><h2>Weekly schedule</h2><?php if(!$schedule):?><p class="muted">Your weekly schedule has not been configured yet. Ask the administrator to set it.</p><?php else:?><div class="grid"><?php foreach($schedule as $s):?><div class="stat"><strong><?=sd_mywork_h($days[(int)$s['day_of_week']]??'Day')?></strong><br><?=$s['is_day_off']?'Day off':sd_mywork_h(substr((string)$s['start_time'],0,5).'–'.substr((string)$s['end_time'],0,5))?></div><?php endforeach;?></div><?php endif;?></section>
<section class="card"><h2>Assigned shifts</h2><div class="tablewrap"><table><thead><tr><th>Date</th><th>Time</th><th>Location</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php foreach($shifts as $s):?><tr><td><?=sd_mywork_h((string)$s['shift_date'])?></td><td><?=sd_mywork_h(substr((string)$s['start_time'],0,5).'–'.substr((string)$s['end_time'],0,5))?></td><td><?=sd_mywork_h((string)($s['location']??'—'))?></td><td><span class="badge"><?=sd_mywork_h(ucfirst((string)$s['status']))?></span></td><td><?=sd_mywork_h((string)($s['notes']??''))?></td></tr><?php endforeach;?><?php if(!$shifts):?><tr><td colspan="5">No shifts scheduled in the recent or upcoming window.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><h2>My tasks</h2><div class="tablewrap"><table><thead><tr><th>Task</th><th>Due</th><th>Priority</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($tasks as $t):?><tr><td><strong><?=sd_mywork_h((string)$t['title'])?></strong><br><?=sd_mywork_h((string)($t['description']??''))?></td><td><?=sd_mywork_h((string)($t['due_at']??'—'))?></td><td><?=sd_mywork_h(ucfirst((string)$t['priority']))?></td><td><span class="badge <?=sd_mywork_h((string)$t['status'])?>"><?=sd_mywork_h(str_replace('_',' ',ucfirst((string)$t['status'])))?></span></td><td><?php if(in_array($t['status'],['pending','in_progress'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=sd_mywork_h(csrf_token())?>"><input type="hidden" name="task_id" value="<?=(int)$t['id']?>"><select name="status"><option value="pending" <?=$t['status']==='pending'?'selected':''?>>Pending</option><option value="in_progress" <?=$t['status']==='in_progress'?'selected':''?>>In progress</option><option value="completed">Completed</option></select> <button type="submit">Save</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$tasks):?><tr><td colspan="5">No tasks assigned.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($user['role']==='stylist'):?><section class="card"><h2>Services assigned to me</h2><div class="tablewrap"><table><thead><tr><th>Service</th><th>Duration</th><th>Price</th><th>Description</th></tr></thead><tbody><?php foreach($myServices as $s):?><tr><td><?=sd_mywork_h((string)$s['name'])?></td><td><?=(int)$s['duration_minutes']?> min</td><td><?=number_format((float)$s['price'],2)?></td><td><?=sd_mywork_h((string)($s['description']??''))?></td></tr><?php endforeach;?><?php if(!$myServices):?><tr><td colspan="4">No services assigned. Contact the administrator.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><h2>My commission summary</h2><div class="grid"><?php foreach(['pending'=>'Pending','approved'=>'Approved','paid'=>'Paid'] as $key=>$label):?><div class="stat"><span class="muted"><?=$label?></span><b><?=number_format($commissionTotals[$key],2)?></b></div><?php endforeach;?></div><p class="muted">These are service-performance records created by an administrator. Ask the administrator about disputed or missing entries.</p><h3>Recent commission entries</h3><div class="tablewrap"><table><thead><tr><th>Performed</th><th>Service</th><th>Price</th><th>Rate</th><th>Commission</th><th>Status</th></tr></thead><tbody><?php foreach($myCommissions as $c):?><tr><td><?=sd_mywork_h((string)$c['performed_at'])?></td><td><?=sd_mywork_h((string)$c['service_name_snapshot'])?></td><td><?=number_format((float)$c['service_price'],2)?></td><td><?=number_format((float)$c['commission_rate'],2)?>%</td><td><?=number_format((float)$c['commission_amount'],2)?></td><td><span class="badge <?=sd_mywork_h((string)$c['status'])?>"><?=sd_mywork_h(ucfirst((string)$c['status']))?></span></td></tr><?php endforeach;?><?php if(!$myCommissions):?><tr><td colspan="6">No commission entries yet.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
</main></body></html>
